
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mvs_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mvs", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.885512169939880e+00, -4.786670477128101e+00, -4.648129393671552e+00, -4.456128961789361e+00, -4.194313143320255e+00, -3.845425051068878e+00, -3.395360441280262e+00, -2.840310827849663e+00, -2.195718892081610e+00, -1.503284430885682e+00, -8.144820574527988e-01, -6.224310430533264e-01, -6.424294755901087e-01, -5.321607858483628e-01, -3.626013676542255e-01, -1.943300255580007e-01, -6.688395571812587e-02, -1.295089293976823e-02, -1.278902680618548e-03, -4.842868111260891e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


